{"command": "cd /tmp && python3 -c "
import numpy as np
from PIL import Image
lab = np.array(Image.open('/tmp/labels.png'))  # (lab+1)*60, so bg=0, clusters 0..3 -> 60,120,180,240
# convert: value//60 -1 ; bg(0)-> -1
lab2 = lab//60 - 1
edge = (lab2==3)
col_counts = edge.sum(axis=0)
row_counts = edge.sum(axis=1)
cols = np.where(col_counts>12)[0]
groups=[]
for c in cols:
    if not groups or c>groups[-1][-1]+1: groups.append([c])
    else: groups[-1].append(c)
print('x edge groups (start,end,mid):', [ (g[0],g[-1], (g[0]+g[-1])//2, col_counts[g].max()) for g in groups])
rows = np.where(row_counts>12)[0]
groups=[]
for r in rows:
    if not groups or r>groups[-1][-1]+1: groups.append([r])
    else: groups[-1].append(r)
print('y edge groups:', [ (g[0],g[-1], (g[0]+g[-1])//2, row_counts[g].max()) for g in groups])
print('shape', lab2.shape)
""}

{"command": "cd /tmp && python3 -c "
import numpy as np
from PIL import Image
lab = np.array(Image.open('/tmp/labels.png'))
lab2 = lab//60 - 1
edge=(lab2==3)
for y in [24,35,47,70,81,93,117,128,163]:
    xs=np.where(edge[y])[0]
    if len(xs): print('y',y,'edge x minmax',xs.min(),xs.max(),'count',len(xs),'span',xs.max()-xs.min())
print('---vertical edges (constant x runs)---')
for x in [26,61,77,96,112,128,147,163,179]:
    ys=np.where(edge[:,x])[0]
    if len(ys): print('x',x,'edge y minmax',ys.min(),ys.max(),'count',len(ys))
""}

